const qolState={wake:null,endAt:0,timer:null,modal:null};
const qolStopRest=()=>{qolState.endAt=0;if(qolState.timer){clearInterval(qolState.timer);qolState.timer=null}qolReleaseWake();document.querySelector('#qol-rest')?.remove();};
const qolRestStart=(seconds=S.set.rest||90)=>{qolState.endAt=Date.now()+seconds*1000;qolAcquireWake();qolRenderRest();if(qolState.timer)clearInterval(qolState.timer);qolState.timer=setInterval(qolRenderRest,250)};
const qolRenderRest=()=>{if(!S.cur||qolState.endAt<=Date.now()){if(qolState.endAt&&S.cur)toast('Rest complete');qolStopRest();return}let el=$('#qol-rest');if(!el){el=document.createElement('div');el.id='qol-rest';el.className='toast';document.body.append(el)}const sec=Math.max(0,Math.ceil((qolState.endAt-Date.now())/1000));el.innerHTML=`<div><small>REST</small><b>${Math.floor(sec/60)}:${String(sec%60).padStart(2,'0')}</b></div><button data-qol=restPlus>+30</button><button data-qol=restStop>Stop</button>`};
const qolPlatePlan=(total,bar=20,plates=[25,20,15,10,5,2.5,1.25,0.5])=>{const side=(num(total)-num(bar))/2;if(side<0)return{exact:false,side:0,plates:[],remainder:Math.abs(side)};let rem=side,out=[];for(const p of plates){const c=Math.floor((rem+1e-9)/p);if(c){out.push({plate:p,count:c});rem=Math.max(0,rem-c*p)}}return{exact:rem<0.01,side,plates:out,remainder:rem}};
const qolRankedNames=()=>Object.keys(R.t||{}).filter(n=>Array.isArray(R.t[n]));
const qolSetupStaples=()=>{for(const [n,c] of Object.entries(QOL_STAPLES)){if(!EX[n])EX[n]={g:c.g,t:c.t};if(R.t?.[c.base])R.alias[n]=c.base}};
const qolApplyCustomAliases=()=>{for(const c of S.custom||[])if(c.rank&&R.t?.[c.rank])R.alias[c.n]=c.rank};
const qolOpenModal=(title,html)=>{qolState.modal?.remove();const m=document.createElement('div');m.className='action-modal';m.style.cssText='position:fixed;inset:0;z-index:1300;display:grid;place-items:center;padding:18px';m.innerHTML=`<div class=action-backdrop></div><div class=action-card style='max-height:88vh;overflow:auto;width:min(680px,96vw)'><div class=qol-modal-head><b>${esc(title)}</b><button data-qol=closeModal aria-label=Close>×</button></div>${html}</div>`;document.body.append(m);qolState.modal=m;return m};
const qolCloseModal=()=>{qolState.modal?.remove();qolState.modal=null};
const qolShowPlate=()=>{const m=qolOpenModal('Plate calculator',`<div class=qol-form><label>Target weight (${S.set.unit||'kg'})<input id=qol-plate-target inputmode=decimal value="${S.set.unit==='lb'?'220.5':'100'}"></label><label>Bar (${S.set.unit||'kg'})<input id=qol-plate-bar inputmode=decimal value="${S.set.unit==='lb'?'44.1':'20'}"></label><button class=cta data-qol=calcPlates>Calculate</button><div id=qol-plate-result class=note><small>Enter a target to calculate plates per side.</small></div></div>`);m.querySelector('#qol-plate-target')?.focus()};
const qolShowProgress=()=>{const lifts=Object.keys(EX).filter(n=>R.t?.[R.alias[n]||n]);const first=lifts[0]||'Bench Press';const m=qolOpenModal('Progress',`<div class=qol-form><label>Lift<select id=qol-progress-lift>${lifts.map(n=>`<option>${esc(n)}</option>`).join('')}</select></label><label>Window<select id=qol-progress-window><option value="90">90 days</option><option value="180">180 days</option><option value="365">1 year</option><option value="all">All time</option></select></label></div><canvas id=qol-chart width="640" height="300"></canvas><div class=note><small>Estimated 1RM and recorded bodyweight. Sets over 12 reps are excluded from the estimate.</small></div>`);m.querySelector('#qol-progress-lift').value=first;m.querySelector('#qol-progress-lift').addEventListener('change',qolDrawProgress);m.querySelector('#qol-progress-window').addEventListener('change',qolDrawProgress);qolDrawProgress()};
const qolDrawProgress=()=>{const c=$('#qol-chart');if(!c)return;const ctx=c.getContext('2d');ctx.clearRect(0,0,c.width,c.height);const n=$('#qol-progress-lift')?.value,w=$('#qol-progress-window')?.value||90,cut=w==='all'?0:Date.now()-Number(w)*864e5,pts=[],bwpts=[];for(const wt of S.workouts){const t=new Date(wt.d+'T23:59:59Z').getTime();if(!t||t<cut)continue;for(const x of wt.ex||[])if(x.n===n)for(const z of x.sets||[]){const b=num(z.bw)||bwAtDate(wt.d),e=rankSetEst(n,z,b);if(e)pts.push({t,e});if(b)bwpts.push({t,b})}}pts.sort((a,b)=>a.t-b.t);bwpts.sort((a,b)=>a.t-b.t);if(!pts.length){ctx.font='16px system-ui';ctx.fillText('No usable sets in this window yet.',24,40);return}const all=pts.map(p=>p.e).concat(bwpts.map(p=>p.b)),lo=Math.min(...all),hi=Math.max(...all),pad=(hi-lo||10)*.12,x0=36,y0=20,w0=c.width-54,h0=c.height-48,tx=t=>x0+(t-pts[0].t)/Math.max(1,pts[pts.length-1].t-pts[0].t)*w0,ty=v=>y0+h0-(v-lo)/Math.max(1,hi-lo)*h0;ctx.strokeStyle='rgba(255,255,255,.12)';ctx.strokeRect(x0,y0,w0,h0);ctx.strokeStyle='#a06cf5';ctx.lineWidth=3;ctx.beginPath();pts.forEach((p,i)=>{const x=tx(p.t),y=ty(p.e);i?ctx.lineTo(x,y):ctx.moveTo(x,y)});ctx.stroke();if(bwpts.length>1){ctx.strokeStyle='#6f7180';ctx.lineWidth=2;ctx.beginPath();const bl= bwpts;bl.forEach((p,i)=>{const x=x0+(p.t-bl[0].t)/Math.max(1,bl[bl.length-1].t-bl[0].t)*w0,y=ty(p.b);i?ctx.lineTo(x,y):ctx.moveTo(x,y)});ctx.stroke()}ctx.font='12px system-ui';ctx.fillStyle='#a06cf5';ctx.fillText('Est. 1RM',x0, c.height-10);ctx.fillStyle='#8e8f98';ctx.fillText('Bodyweight',x0+82,c.height-10);};
const qolProfileCard=()=>{if(view!=='settings'||$('#qol-profile-card'))return;const wrap=document.createElement('section');wrap.id='qol-profile-card';wrap.className='set';wrap.innerHTML=`<p class=q>Quality of life</p><div class=row><div><b>Units</b><small>One setting for sliders, typed entry and rank sheets.</small></div><div class=chips><button class="pill ${(S.set.unit||'kg')==='kg'?'dark':''}" data-qol=unit data-v=kg>kg</button><button class="pill ${(S.set.unit||'kg')==='lb'?'dark':''}" data-qol=unit data-v=lb>lb</button></div></div><div class=row><div><b>Age adjustment</b><small>Interpolated estimate; turn it off for adult-baseline rankings.</small></div><button class="toggle ${S.set.ageAdjust!==false?'on':''}" data-qol=ageAdjust><span class=track><i></i></span><small>${S.set.ageAdjust!==false?'On':'Off'}</small></button></div><div class=row><div><b>Height / ROM adjustment</b><small>Mild longer-ROM correction used by Lift's rankings.</small></div><button class="toggle ${S.set.heightAdjust!==false?'on':''}" data-qol=heightAdjust><span class=track><i></i></span><small>${S.set.heightAdjust!==false?'On':'Off'}</small></button></div><div class=row><div><b>Rest timer</b><small>Starts after each logged set and keeps the screen awake when supported.</small></div><label class=qol-inline><input id=qol-rest-setting type=number min=30 max=600 step=15 value="${S.set.rest||90}"> sec</label></div><div class=chips><button class=pill data-qol=progress>Progress charts</button><button class=pill data-qol=plate>Plate calculator</button></div><p class=q>Custom exercise ranking</p><div id=qol-custom-map>${(S.custom||[]).length?(S.custom||[]).map(c=>`<div class=row><div><b>${esc(c.n)}</b><small>Rank against a standard lift.</small></div><select data-qol-map="${esc(c.n)}"><option value="">Unranked</option>${qolRankedNames().map(n=>`<option value="${esc(n)}" ${c.rank===n?'selected':''}>${esc(n)}</option>`).join('')}</select></div>`).join(''):'<small>No custom exercises yet.</small>'}</div>`;$('#v')?.append(wrap)};
const qolHistoryCard=()=>{if(view!=='history'||$('#qol-history-card'))return;const wrap=document.createElement('div');wrap.id='qol-history-card';wrap.className='note';wrap.innerHTML=`<div class=chips><button class=pill data-qol=progress>Progress charts</button><button class=pill data-qol=plate>Plate calculator</button></div><small>See estimated 1RM trend, bodyweight trend, and use the same tools without leaving History.</small>`;$('#v')?.prepend(wrap)};
const qolWorkoutBits=()=>{if(view!=='today'||!S.cur)return;const p=document.querySelector('.picker');if(!p)return;const n=S.cur.ex?.[ci]?.n,prev=qolPrevSet(n);if(!document.querySelector('#qol-workout-tools')){const box=document.createElement('div');box.id='qol-workout-tools';box.innerHTML=`<div class=qol-last><div><small>LAST TIME</small><b>${prev?`${prev.kg} kg × ${prev.reps}${prev.rpe?' · RPE '+prev.rpe:''}`:'No previous set'}</b>${prev?.date?`<small>${prev.date}</small>`:''}</div>${prev?'<button class=pill data-qol=repeatLast>Repeat</button>':''}</div><div class=qol-typed><label>Weight <span>${S.set.unit||'kg'}</span><input id=qol-weight inputmode=decimal value="${qolFormat(dr.kg)}" step="${Math.max(.1,dr.st*((S.set.unit||'kg')==='lb'?2.20462:1))}"></label><label>Reps<input id=qol-reps inputmode=numeric value="${dr.reps}" step=1 min=1 max=30></label></div><div class=qol-notes><label>RPE <select id=qol-rpe><option value="">RPE</option>${[6,7,8,9,10].map(x=>`<option value="${x}">${x}</option>`).join('')}</select></label><label class=qol-grow>Note <input id=qol-note placeholder="Optional set note"></label></div>`;p.parentElement?.insertBefore(box,p)}else{const w=$('#qol-weight');if(w&&document.activeElement!==w)w.value=qolFormat(dr.kg);const r=$('#qol-reps');if(r&&document.activeElement!==r)r.value=dr.reps;const u=document.querySelector('#qol-workout-tools .qol-typed label span');if(u)u.textContent=S.set.unit||'kg'}qolAnnotateSets()};
const qolAnnotateSets=()=>{const c=S.cur?.ex?.[ci];if(!c)return;document.querySelectorAll('.srow').forEach((row,i)=>{const z=c.sets[i];row.querySelector('.qol-meta')?.remove();if(z?.rpe||z?.note){const m=document.createElement('small');m.className='qol-meta';m.textContent=[z.rpe?'RPE '+z.rpe:'',z.note||''].filter(Boolean).join(' · ');row.append(m)}})};
const qolRender=()=>{qolProfileCard();qolHistoryCard();qolWorkoutBits();if(S.cur&&view==='today'&&qolState.endAt)qolRenderRest()};
const qolStart=()=>{qolSetupStaples();qolApplyCustomAliases();const observer=new MutationObserver(()=>requestAnimationFrame(qolRender));observer.observe($('#v'),{childList:true,subtree:true});qolRender();
 const origLog=A.log;A.log=()=>{const note=$('#qol-note')?.value.trim()||'',rpe=num($('#qol-rpe')?.value),before=Date.now();origLog();const z=S.cur?.ex?.[ci]?.sets?.at(-1);if(z){z.note=note||undefined;z.rpe=rpe||undefined;z.bw=bwAtDate(S.cur.d);z.height=num(S.set.heightCm)||undefined;z.loggedAt=before;save()}qolRestStart(S.set.rest||90);qolRender()};
 A.start=A.start;document.addEventListener('input',e=>{const id=e.target.id;if(id==='qol-weight'){dr.kg=Math.min(dr.hi,Math.max(dr.lo,qolKg(e.target.value)));syncPickers()}else if(id==='qol-reps'){dr.reps=Math.min(30,Math.max(1,Math.round(num(e.target.value)||1)));syncPickers()}else if(id==='qol-rest-setting'){S.set.rest=Math.min(600,Math.max(30,Math.round(num(e.target.value)/15)*15));save()}});
 document.addEventListener('change',e=>{const s=e.target;if(s.matches('[data-qol-map]')){const name=s.dataset.qolMap,c=S.custom.find(x=>x.n===name);if(c){c.rank=s.value||'';if(c.rank)R.alias[name]=c.rank;else delete R.alias[name];save();render()}}});
 document.addEventListener('click',e=>{const b=e.target.closest('[data-qol]');if(!b)return;const a=b.dataset.qol;if(a==='progress')qolShowProgress();if(a==='plate')qolShowPlate();if(a==='closeModal'||a==='modalBg'||e.target.classList.contains('qol-modal-bg'))qolCloseModal();if(a==='restPlus')qolState.endAt+=30e3;if(a==='restStop')qolStopRest();if(a==='repeatLast'){const z=qolPrevSet(S.cur?.ex?.[ci]?.n);if(z){dr.kg=num(z.kg);dr.reps=num(z.reps);syncPickers();qolRender()}}if(a==='unit'){S.set.unit=b.dataset.v;save();render()}if(a==='ageAdjust'){S.set.ageAdjust=S.set.ageAdjust===false;Object.values(S.rk).forEach(r=>r.age=S.set.age||r.age);save();render();toast(S.set.ageAdjust?'Age adjustment on':'Age adjustment off')}if(a==='heightAdjust'){S.set.heightAdjust=S.set.heightAdjust===false;save();render();toast(S.set.heightAdjust?'Height / ROM adjustment on':'Height / ROM adjustment off')}if(a==='calcPlates'){const total=qolKg($('#qol-plate-target')?.value),bar=qolKg($('#qol-plate-bar')?.value)||20,r=qolPlatePlan(total,bar);const out=r.plates.length?r.plates.map(x=>`${x.count} × ${x.plate} kg / side`).join('<br>'):'No plates needed';const rem=r.exact?'Exact load':'Closest possible with current plate set';const el=$('#qol-plate-result');if(el)el.innerHTML=`<b>${r.side.toFixed(2)} kg / side</b><br>${out}<br><small>${rem}${r.exact?'':` · ${r.remainder.toFixed(2)} kg left per side`}</small>`}});
 document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'&&qolState.endAt>Date.now())qolAcquireWake()});
};
setTimeout(qolStart,0);

